 760→  const tabs = [
 761→    { id: "all", content: `All (${stats.total})` },
 762→    { id: "under_review", content: `Under Review (${stats.under_review})` },
 763→    { id: "planned", content: `Planned (${stats.planned})` },
 764→    { id: "in_progress", content: `In Progress (${stats.in_progress})` },
 765→    { id: "done", content: `Done (${stats.done})` },
 766→  ];
 767→
 768→  // ------------------------------------------------------------------
 769→  // Render
 770→  // ------------------------------------------------------------------
 771→  return (
 772→    <Page
 773→      title="Feature Requests"
 774→      subtitle="Vote on features or suggest new ones. We review every request and ship based on community votes."
 775→      backAction={{ onAction: () => navigate("/app") }}
 776→      primaryAction={{
 777→        content: "Suggest a Feature",
 778→        icon: PlusIcon,
