1169→              </Banner>
1170→            )}
1171→            <TextField
1172→              label="Title"
1173→              value={newTitle}
1174→              onChange={setNewTitle}
1175→              placeholder="e.g. Export ZIP codes to CSV"
1176→              autoComplete="off"
1177→              maxLength={150}
1178→              showCharacterCount
1179→              helpText="Keep it short and descriptive."
1180→            />
1181→            <TextField
1182→              label="Description"
1183→              value={newDescription}
1184→              onChange={setNewDescription}
1185→              placeholder="Describe the feature and why it would be valuable..."
1186→              autoComplete="off"
1187→              multiline={4}
1188→              maxLength={MAX_DESCRIPTION_LENGTH}
1189→              showCharacterCount
1190→              helpText="The more context you provide, the better we can understand your needs."
1191→            />
