                        { key: "success", label: "Success", color: "#22c55e" },
                        { key: "error", label: "Blocked", color: "#ef4444" },
                        { key: "notfound", label: "Not Found", color: "#f59e0b" },
                      ] as const).map(s => (
                        <button
                          key={s.key}
                          type="button"
                          onClick={() => setPreviewState(s.key)}
                          style={{
