          <span className="zcc-btn-label">{cfg.buttonText}</span>
        </button>
      </div>

      {/* Success result — matches storefront rendering */}
      {previewState === "success" && (
        <div className="zcc-result ok">
          <div className="zcc-result-icon">{checkCircleIcon}</div>
