131→// ─── Action ───────────────────────────────────────────────────────────────────
132→
133→export const action = async ({ request }: ActionFunctionArgs): Promise<
134→  | { error: string }
135→  | { success: boolean; message: string }
136→  | null
137→> => {
138→  const { session, billing } = await authenticate.admin(request);
139→  const shop = session.shop;
140→  const formData = await request.formData();
141→  const intent = String(formData.get("intent"));
142→
143→  if (intent === "subscribe") {
144→    const plan = String(formData.get("plan"));
145→    const returnUrl = `${process.env.SHOPIFY_APP_URL}/app/pricing`;
146→    try {
147→      /* eslint-disable @typescript-eslint/no-explicit-any */
148→      // billing.request() throws a redirect Response to Shopify's
149→      // billing confirmation page — we must let it propagate.
150→      await billing.request({
151→        plan: plan as any,
152→        isTest: process.env.NODE_ENV !== "production",
153→        returnUrl,
154→      });
155→      /* eslint-enable @typescript-eslint/no-explicit-any */
156→      return null;
157→    } catch (error) {
158→      // Re-throw Response redirects so React Router / App Bridge handles them
159→      if (error instanceof Response) throw error;
160→      // BillingError has errorData with Shopify userErrors
161→      const errorData = (error as { errorData?: Array<{ field?: string; message?: string }> }).errorData;
162→      const details = errorData?.map((e) => e.message).join(", ");
163→      const message = details || (error instanceof Error ? error.message : String(error));
164→
165→      // Provide a helpful message for common billing errors
166→      if (message.includes("Custom apps cannot use the Billing API")) {
167→        return {
168→          error: "Billing is not available for custom apps. Please change your app distribution to 'Public' in the Shopify Partner Dashboard.",
169→        };
170→      }
171→      return {
172→        error: `Failed to initiate subscription: ${message}`,
173→      };
174→    }
175→  }
176→
177→  // Set plan directly in database (for custom apps where Billing API is unavailable)
178→  if (intent === "test-set-plan") {
179→    const tier = String(formData.get("tier")) as import("../plans").PlanTier;
180→    const validTiers = ["free", "starter", "pro", "ultimate"];
181→    if (!validTiers.includes(tier)) {
182→      return { error: `Invalid plan tier: ${tier}` };
183→    }
184→    const planId = tier === "free" ? "free" : `${tier.charAt(0).toUpperCase() + tier.slice(1)} Monthly`;
185→    await db.subscription.upsert({
186→      where: { shop },
187→      create: { shop, planId, billingInterval: "monthly", status: "active" },
188→      update: { planId, billingInterval: "monthly", status: "active", shopifySubscriptionId: null },
189→    });
190→    return { success: true, message: `Plan set to ${tier.charAt(0).toUpperCase() + tier.slice(1)}.` };
191→  }
192→
193→  if (intent === "cancel") {
194→    try {
195→      const sub = await getShopSubscription(shop);
196→      if (sub.shopifySubscriptionId) {
197→        await billing.cancel({
198→          subscriptionId: sub.shopifySubscriptionId,
199→          isTest: process.env.NODE_ENV !== "production",
200→          prorate: true,
201→        });
202→      }
203→      await cancelShopSubscription(shop);
204→      return {
205→        success: true,
206→        message: "Subscription cancelled. You are now on the Free plan.",
207→      };
208→    } catch {
209→      return { error: "Failed to cancel subscription. Please try again." };
210→    }
211→  }
212→
213→  return null;
214→};
215→
216→// ─── Feature row ─────────────────────────────────────────────────────────────
217→
218→function PlanFeature({ feature }: { feature: string }) {
219→  return (
220→    <InlineStack gap="200" blockAlign="start" wrap={false}>
221→      <Box>
222→        <Icon source={CheckCircleIcon} tone="success" />
223→      </Box>
224→      <Text as="span" variant="bodyMd">
225→        {feature}
226→      </Text>
227→    </InlineStack>
228→  );
229→}
230→
231→// ─── Plan card ────────────────────────────────────────────────────────────────
232→
233→type PlanCardProps = {
234→  plan: (typeof PLANS_DATA)[keyof typeof PLANS_DATA];
235→  isAnnual: boolean;
236→  currentTier: string;
237→  onSubscribe: (planName: string) => void;
238→  onRequestCancel: () => void;
239→  loadingPlan: string | null;
240→};
241→
242→function PlanCard({
243→  plan,
244→  isAnnual,
245→  currentTier,
246→  onSubscribe,
247→  onRequestCancel,
248→  loadingPlan,
249→}: PlanCardProps) {
250→  const isCurrent = currentTier === plan.id;
251→  const isBestValue = "bestValue" in plan && plan.bestValue;
252→  const isCurrentPaid = currentTier !== "free";
253→  const isDowngradeToFree = plan.id === "free" && isCurrentPaid;
254→
255→  const TIER_ORDER: Record<string, number> = {
256→    free: 0,
257→    starter: 1,
258→    pro: 2,
259→    ultimate: 3,
260→  };
261→  const isUpgrade =
262→    !isCurrent &&
263→    plan.id !== "free" &&
264→    (TIER_ORDER[plan.id] ?? 0) > (TIER_ORDER[currentTier] ?? 0);
265→
266→  const shopifyPlan = isAnnual
267→    ? plan.shopifyPlanAnnual
268→    : plan.shopifyPlanMonthly;
269→
270→  const displayPrice = isAnnual ? plan.annualMonthlyPrice : plan.monthlyPrice;
271→
272→  let buttonContent = "Start 7-day free trial";
273→  if (isCurrent) {
274→    buttonContent = "Current plan";
275→  } else if (isDowngradeToFree) {
276→    buttonContent = "Downgrade to Free";
277→  } else if (isUpgrade) {
278→    buttonContent = `Upgrade to ${plan.name}`;
279→  } else if (!isCurrent && plan.id !== "free" && isCurrentPaid) {
280→    buttonContent = `Switch to ${plan.name}`;
281→  }
282→
283→  const handleClick = () => {
284→    if (isCurrent) return;
285→    if (isDowngradeToFree) {
286→      onRequestCancel();
287→    } else if (shopifyPlan) {
288→      onSubscribe(shopifyPlan);
289→    }
290→  };
291→
292→  const isThisLoading = loadingPlan === (shopifyPlan ?? "cancel");
293→
294→  return (
295→    <Card>
296→      <BlockStack gap="400">
297→
298→        {/* Plan name + badges */}
299→        <BlockStack gap="100">
300→          <InlineStack align="space-between" blockAlign="center">
301→            <Text as="h3" variant="headingMd" fontWeight="bold">
302→              {plan.name}
303→            </Text>
304→            <InlineStack gap="150">
305→              {isBestValue && (
306→                <Badge tone="info" icon={StarIcon}>
307→                  Most popular
308→                </Badge>
309→              )}
310→              {isCurrent && <Badge tone="success">Active</Badge>}
311→            </InlineStack>
312→          </InlineStack>
313→          <Text as="p" variant="bodySm" tone="subdued">
314→            {plan.description}
315→          </Text>
316→        </BlockStack>
317→
318→        <Divider />
319→
320→        {/* Price */}
321→        <BlockStack gap="100">
322→          {plan.monthlyPrice === 0 ? (
323→            <>
324→              <Text as="p" variant="headingXl" fontWeight="bold">
325→                Free
326→              </Text>
327→              <Text as="p" variant="bodySm" tone="subdued">
328→                forever
329→              </Text>
330→            </>
331→          ) : (
332→            <>
333→              <InlineStack gap="100" blockAlign="baseline">
334→                <Text as="p" variant="headingXl" fontWeight="bold">
335→                  ${displayPrice}
336→                </Text>
337→                <Text as="p" variant="bodySm" tone="subdued">
338→                  / month
339→                </Text>
340→              </InlineStack>
341→              <Text as="p" variant="bodySm" tone="subdued">
342→                {isAnnual
343→                  ? `billed $${plan.annualPrice} / year`
344→                  : `or $${plan.annualMonthlyPrice}/mo billed annually`}
345→              </Text>
346→            </>
347→          )}
348→        </BlockStack>
349→
350→        {/* CTA button */}
351→        <Button
352→          variant={isCurrent ? "secondary" : "primary"}
353→          tone={isDowngradeToFree ? "critical" : undefined}
354→          onClick={handleClick}
355→          disabled={isCurrent}
356→          loading={isThisLoading}
357→          fullWidth
358→        >
359→          {buttonContent}
360→        </Button>
361→
362→        <Divider />
363→
364→        {/* Features list */}
365→        <BlockStack gap="300">
366→          {plan.features.map((f) => (
367→            <PlanFeature key={f} feature={f} />
368→          ))}
369→        </BlockStack>
370→
371→      </BlockStack>
372→    </Card>
373→  );
374→}
375→
376→// ─── Page ─────────────────────────────────────────────────────────────────────
377→
378→export default function PricingPage() {
379→  const { subscription } = useLoaderData<typeof loader>();
380→  const fetcher = useFetcher<typeof action>();
381→  const navigate = useNavigate();
382→  const shopify = useAppBridge();
383→
384→  const [isAnnual, setIsAnnual] = useState(
385→    subscription.billingInterval === "annual",
386→  );
387→  const [loadingPlan, setLoadingPlan] = useState<string | null>(null);
388→  const [cancelModalOpen, setCancelModalOpen] = useState(false);
389→
390→  const data = fetcher.data;
391→  const isFetching = fetcher.state !== "idle";
392→
393→  // Toast for success, Banner for errors (errors must not auto-dismiss)
394→  useEffect(() => {
395→    if (!isFetching) setLoadingPlan(null);
396→    if (data && "message" in data && data.message) {
397→      shopify.toast.show(data.message as string);
398→    }
399→  }, [data, isFetching, shopify]);
400→
401→  const actionError =
402→    data && "error" in data && data.error ? (data.error as string) : null;
403→
404→  const handleSubscribe = useCallback(
405→    (planName: string) => {
406→      setLoadingPlan(planName);
407→      const fd = new FormData();
408→      fd.set("intent", "subscribe");
409→      fd.set("plan", planName);
410→      fetcher.submit(fd, { method: "POST" });
411→    },
412→    [fetcher],
413→  );
414→
415→  const handleConfirmCancel = useCallback(() => {
416→    setCancelModalOpen(false);
417→    setLoadingPlan("cancel");
418→    const fd = new FormData();
419→    fd.set("intent", "cancel");
420→    fetcher.submit(fd, { method: "POST" });
421→  }, [fetcher]);
422→
423→  const currentTier = subscription.planTier;
424→  const currentPlanName =
425→    PLANS_DATA[currentTier as keyof typeof PLANS_DATA]?.name ?? "Free";
426→
427→  // Suggest next tier for upgrade banner
428→  const nextTier =
429→    currentTier === "free"
430→      ? "starter"
431→      : currentTier === "starter"
432→        ? "pro"
433→        : null;
434→
435→  return (
436→    <Page
437→      title="Pricing"
438→      subtitle="Choose the plan that's right for your store"
439→      backAction={{ onAction: () => navigate("/app") }}
440→    >
441→      <Box paddingBlockEnd="1600">
442→      <Layout>
443→        {actionError && (
444→          <Layout.Section>
445→            <Banner tone="critical" title="Billing error">
446→              <Text as="p" variant="bodyMd">{actionError}</Text>
447→            </Banner>
448→          </Layout.Section>
449→        )}
450→        <Layout.Section>
451→          <BlockStack gap="600">
452→
453→            {/* Current plan status */}
454→            {nextTier ? (
455→              <Banner
456→                tone="info"
457→                title={`You're on the ${currentPlanName} plan`}
458→                action={{
459→                  content: `Upgrade to ${PLANS_DATA[nextTier].name}`,
460→                  onAction: () => {
461→                    const plan = isAnnual
462→                      ? PLANS_DATA[nextTier].shopifyPlanAnnual
463→                      : PLANS_DATA[nextTier].shopifyPlanMonthly;
464→                    if (plan) handleSubscribe(plan);
465→                  },
466→                }}
467→              >
468→                <Text as="p" variant="bodyMd">
469→                  {currentTier === "free"
470→                    ? "You have up to 20 allowed zip codes and basic widget access. Upgrade to unlock more features."
471→                    : "Upgrade to Pro for unlimited zip codes, blocked areas, full waitlist, and more."}
472→                </Text>
473→              </Banner>
474→            ) : (
475→              <Banner tone="success" title={`You're on the ${currentPlanName} plan`}>
476→                <InlineStack gap="200" blockAlign="center">
477→                  <Badge tone="success">Active</Badge>
478→                  <Text as="p" variant="bodyMd">
479→                    {currentTier === "ultimate"
480→                      ? "You have full access to all features including VIP support and API access."
481→                      : "You have unlimited zip codes, blocked areas, delivery rules, and more."}
482→                  </Text>
483→                </InlineStack>
484→              </Banner>
