534→            </InlineGrid>
535→
536→            {/* Trial footnote */}
537→            {(currentTier === "free" || currentTier === "starter") && (
538→              <Text
539→                as="p"
540→                variant="bodySm"
541→                tone="subdued"
542→                alignment="center"
543→              >
544→                All paid plans include a 7-day free trial. No credit card
